SELECT i.item_category AS CATEGORY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 2 THEN o.quantity ELSE 0 END), 0) AS MONDAY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 3 THEN o.quantity ELSE 0 END), 0) AS TUESDAY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 4 THEN o.quantity ELSE 0 END), 0) AS WEDNESDAY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 5 THEN o.quantity ELSE 0 END), 0) AS THURSDAY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 6 THEN o.quantity ELSE 0 END), 0) AS FRIDAY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 7 THEN o.quantity ELSE 0 END), 0) AS SATURDAY, IFNULL(SUM(CASE WHEN DAYOFWEEK(o.order_date) = 1 THEN o.quantity ELSE 0 END), 0) AS SUNDAY FROM Items i LEFT JOIN Orders o ON i.item_id = o.item_id GROUP BY i.item_category ORDER BY CATEGORY;
